SourceCode.Declaration:
/// <summary>
/// What a hazard or blind count asks to be counted: an item (with optional product dimensions), a
/// location, or an item at a location. Hazard rows come from the outside system
/// (HSMobileOpsCountRequestService); blind rows are added by the supervisor in the control center.
/// </summary>
public class HSMobileOpsCountItem extends common
{
}

Method.Source:
/// <summary>
/// Numbers the line and keeps the item's name; the count's Requested items figure follows.
/// </summary>
public void insert()
{
    HSMobileOpsCountItem last;

    if (!this.LineNum)
    {
        select maxOf(LineNum) from last where last.MasterRecId == this.MasterRecId;
        this.LineNum = last.LineNum + 1;
    }
    this.ItemName = this.ItemId ? subStr(InventTable::find(this.ItemId).defaultProductName(), 1, 60) : '';
    super();
    HSMobileOpsCountItem::recount(this.MasterRecId);
}

public void update()
{
    this.ItemName = this.ItemId ? subStr(InventTable::find(this.ItemId).defaultProductName(), 1, 60) : '';
    super();
}

public void delete()
{
    RefRecId masterRecId = this.MasterRecId;

    super();
    HSMobileOpsCountItem::recount(masterRecId);
}

/// <summary>
/// Only a supervisor's open blind count takes items from this form: a hazard count's come
/// from the outside system, and a wall to wall count counts everything.
/// </summary>
public boolean validateWrite()
{
    boolean                ret = super();
    HSMobileOpsCountMaster master = HSMobileOpsCountControl::masterOf(this.MasterRecId);

    if (master.Status != HSMobileOpsCountMasterStatus::Open)
    {
        ret = checkFailed(strFmt('%1 is %2 - its items can no longer be changed.', master.MasterId, master.Status));
    }
    else if (master.MasterType != HSMobileOpsCountMasterType::Blind)
    {
        ret = checkFailed(master.MasterType == HSMobileOpsCountMasterType::Hazard
            ? "A hazard count's items come from the outside system."
            : 'A wall to wall count counts everything - it has no item list.');
    }
    if (ret && !this.ItemId && !this.WMSLocationId)
    {
        ret = checkFailed('Enter an item, a location, or both.');
    }
    if (ret && this.ItemId && !InventTable::exist(this.ItemId))
    {
        ret = checkFailed(strFmt('Item %1 does not exist.', this.ItemId));
    }
    if (ret && this.WMSLocationId && !WMSLocation::find(this.WMSLocationId, master.InventLocationId).RecId)
    {
        ret = checkFailed(strFmt('Location %1 is not in warehouse %2.', this.WMSLocationId, master.InventLocationId));
    }
    return ret;
}

public boolean validateDelete()
{
    boolean                ret = super();
    HSMobileOpsCountMaster master = HSMobileOpsCountControl::masterOf(this.MasterRecId);

    if (ret && (master.Status != HSMobileOpsCountMasterStatus::Open || master.MasterType != HSMobileOpsCountMasterType::Blind))
    {
        ret = checkFailed("Only an open blind count's items can be removed.");
    }
    return ret;
}

public static void recount(RefRecId _masterRecId)
{
    HSMobileOpsCountItem   item;
    HSMobileOpsCountMaster master;

    select count(RecId) from item where item.MasterRecId == _masterRecId;
    ttsbegin;
    select forUpdate firstonly master where master.RecId == _masterRecId;
    if (master.RecId && master.RequestedItemCount != int642int(item.RecId))
    {
        master.RequestedItemCount = int642int(item.RecId);
        master.update();
    }
    ttscommit;
}
